import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.XJu5filh.js";import"./chunks/assets.DWopfgZq.js";var c=JSON.parse(`{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"begin/start.md","filePath":"begin/start.md","lastUpdated":1792237609000}`),l={name:`begin/start.md`};function u(i,c,l,u,d,f){let p=s(`Badge`);return e(),o(`div`,null,[c[4]||=r(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to “快速开始”">​</a></h1><p>扩展、Windows、macOS 和 Android 安装包统一在<a href="https://github.com/Waaatanuki/tarou-downloads/releases/latest" target="_blank" rel="noreferrer">最新版本下载页</a>提供，选择与你的平台对应的附件即可。安装包名称中的版本号以发布页为准。</p><table tabindex="0"><thead><tr><th>平台</th><th>下载附件</th></tr></thead><tbody><tr><td>Chrome 扩展</td><td><code>Tarou-Extension-&lt;version&gt;.zip</code></td></tr><tr><td>Windows x64</td><td><code>Tarou-&lt;version&gt;-win-x64-setup.exe</code></td></tr><tr><td>macOS Apple Silicon</td><td><code>Tarou-&lt;version&gt;-mac-arm64.dmg</code></td></tr><tr><td>Android</td><td><code>Tarou-Android-&lt;version&gt;.apk</code></td></tr></tbody></table><h2 id="chrome-扩展" tabindex="-1">Chrome 扩展 <a class="header-anchor" href="#chrome-扩展" aria-label="Permalink to “Chrome 扩展”">​</a></h2><p>扩展需要支持侧边栏等相关扩展 API 的 Chromium 内核浏览器，例如：</p><ul><li>Chrome</li><li>SRWare Iron</li><li>Edge</li></ul><p>扩展声明的 Chromium 最低版本为116。不同浏览器对侧边栏和调试 API 的支持可能有差异，不能仅凭内核版本判断兼容性。</p><h3 id="获取插件" tabindex="-1">获取插件 <a class="header-anchor" href="#获取插件" aria-label="Permalink to “获取插件”">​</a></h3><p>从<a href="https://github.com/Waaatanuki/tarou-downloads/releases/latest" target="_blank" rel="noreferrer">最新版本下载页</a>下载 <code>Tarou-Extension-&lt;version&gt;.zip</code>，解压缩以后有个 <code>Chrome-Extension-Tarou</code> 文件夹，里面就是插件文件。</p><p>将该文件夹移动到一个固定位置，比如E:\\gbf\\Chrome-Extension-Tarou，之后尽量不要改动位置。</p><h3 id="加载插件" tabindex="-1">加载插件 <a class="header-anchor" href="#加载插件" aria-label="Permalink to “加载插件”">​</a></h3><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>演示截图为Iron浏览器，Chrome差不多，Edge稍有区别但也差别不大。</p></div><ul><li><p>打开浏览器的管理扩展程序页面</p><p><img src="/tarou-docs/assets/img/start-img1.png" alt="alt text" width="511" height="445"></p></li><li><p>打开右上角<code>开发者模式</code></p><p><img src="/tarou-docs/assets/img/start-img2.png" alt="alt text" width="631" height="106"></p></li><li><p>点击<code>加载已解压的扩展程序</code>选择Chrome-Extension-Tarou文件夹，加载太郎插件</p><p><img src="/tarou-docs/assets/img/start-img3.png" alt="alt text" width="546" height="253"></p></li><li><p>看到这个插件面板就说明加载成功</p><p><img src="/tarou-docs/assets/img/start-img4.png" alt="alt text" width="410" height="212"></p></li></ul><h3 id="更新插件" tabindex="-1">更新插件 <a class="header-anchor" href="#更新插件" aria-label="Permalink to “更新插件”">​</a></h3><p>发现新版本时，菜单头像上方会出现蓝色下载按钮，点击可下载新版 ZIP；也可以直接从<a href="https://github.com/Waaatanuki/tarou-downloads/releases/latest" target="_blank" rel="noreferrer">最新版本下载页</a>下载。</p><p>假设插件存放在E:\\gbf\\Chrome-Extension-Tarou</p>`,16),n(`ul`,null,[c[2]||=n(`li`,null,[n(`p`,null,`删除Chrome-Extension-Tarou文件夹`)],-1),c[3]||=n(`li`,null,[n(`p`,null,`把新下载的压缩包解压后的Chrome-Extension-Tarou文件夹放到E:\\gbf，使插件路径依然保持E:\\gbf\\Chrome-Extension-Tarou`)],-1),n(`li`,null,[n(`p`,null,[c[0]||=t(`在浏览器的管理扩展程序页面重新加载插件`,-1),a(p,{type:`danger`,text:`重要`})]),c[1]||=n(`p`,null,[n(`img`,{src:`/tarou-docs/assets/img/start-img5.png`,alt:`alt text`,width:`404`,height:`212`})],-1)])]),c[5]||=r(`<div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>更新文件后需要重新加载扩展；如果游戏页面仍使用旧脚本，再刷新游戏页面。不要删除浏览器中已安装的扩展来更新，以免清空其本地数据。</p></div><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to “Windows”">​</a></h2><ol><li>下载 Windows x64 的 <code>setup.exe</code> 安装包并运行，按安装向导完成安装。</li><li>启动 Tarou，在内嵌游戏页面登录，使用书签栏和右侧功能区。</li></ol><p>有新版本时，菜单头像上方会显示蓝色下载按钮。第一次点击下载更新，完成后按钮变为“重启安装”；再次点击才会退出并安装。也可以退出 Tarou 后运行新版安装包覆盖安装，保留本地配置和记录。</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to “macOS”">​</a></h2><p>当前提供 Apple Silicon（arm64）版本。</p><ol><li>下载并打开 <code>mac-arm64.dmg</code>，将 <code>Tarou.app</code> 拖入「应用程序 / Applications」。</li><li>从「应用程序」打开 Tarou。如果 macOS 提示 Apple 无法验证应用，确认安装包来自上面的项目发布页后，进入「系统设置 → 隐私与安全性」，找到 Tarou 并选择「仍要打开」。</li></ol><p>新版本按钮通过浏览器下载 DMG，需要手动安装。更新时先完全退出 Tarou，再将新版 <code>Tarou.app</code> 拖入原安装位置，选择「替换」后重新启动；正常覆盖安装保留本地配置和记录。</p><h2 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to “Android”">​</a></h2><ol><li>在手机上下载 <code>Tarou-Android-&lt;version&gt;.apk</code> 并打开。</li><li>如果系统要求授权，在提示中允许当前浏览器或文件管理器安装应用，再返回完成安装。</li><li>打开 Tarou，通过游戏页面登录，使用底部工具栏打开功能面板。</li></ol><p>新版本按钮通过系统浏览器下载最新版 APK，下载后手动覆盖安装。沿用同一应用的正式安装包覆盖更新会保留本地数据。</p><h2 id="浏览器启动项" tabindex="-1">浏览器启动项 <a class="header-anchor" href="#浏览器启动项" aria-label="Permalink to “浏览器启动项”">​</a></h2><h3 id="silent-debugger-extension-api" tabindex="-1">--silent-debugger-extension-api <a class="header-anchor" href="#silent-debugger-extension-api" aria-label="Permalink to “--silent-debugger-extension-api”">​</a></h3><p>有些数据需要调用插件的debuggerAPI，这时候页面顶部会提示<code>Tarou已开始调试此浏览器</code>，这个提示信息不能关闭，但是可以通过这个命令来隐藏</p><h3 id="disable-backgrounding-occluded-windows" tabindex="-1">--disable-backgrounding-occluded-windows <a class="header-anchor" href="#disable-backgrounding-occluded-windows" aria-label="Permalink to “--disable-backgrounding-occluded-windows”">​</a></h3><p>该命令可以让浏览器在后台也能运行，比如点了FA之后用别的页面盖住，还能继续动。这个启动项跟插件无关，但是比较常用就也放在这了</p><h3 id="如何添加启动项命令" tabindex="-1">如何添加启动项命令 <a class="header-anchor" href="#如何添加启动项命令" aria-label="Permalink to “如何添加启动项命令”">​</a></h3><details class="details custom-block"><summary>Windows</summary><p>右击浏览器图标在属性-目标最后追加启动项命令</p><p><img src="/tarou-docs/assets/img/start-img6.png" alt="alt text" width="397" height="185"></p><p>命令之间有个空格，添加完之后类似于 ...chrome.exe&quot; --silent-debugger-extension-api --disable-backgrounding-occluded-windows</p><p><img src="/tarou-docs/assets/img/start-img10.png" alt="alt text" width="876" height="174"></p><p>Edge需要额外关闭上方浏览器设置中的两个选项，关闭后杀掉浏览器进程再次启动生效。</p></details><details class="details custom-block"><summary>macOS</summary><ol><li><p>打开启动台-其他-自动操作，或者在终端里输入<code>open -a &quot;Automator&quot;</code><img src="/tarou-docs/assets/img/start-img7.png" alt="alt text" width="156" height="169"></p></li><li><p>选择<code>应用程序</code>-<code>实用工具</code>-<code>运行Shell脚本</code><img src="/tarou-docs/assets/img/start-img8.png" alt="alt text" width="991" height="625"></p></li><li><p>在Shell脚本框中根据使用的浏览器输入命令，<code>浏览器地址 --silent-debugger-extension-api --disable-backgrounding-occluded-windows</code><img src="/tarou-docs/assets/img/start-img9.png" alt="alt text" width="612" height="176"></p><p>上图是我自己使用的Iron浏览器地址，不同版本不同浏览器的位置可能不一样，需要根据实际情况填写浏览器的最终执行程序地址。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>如果路径中有空格，需要在空格前加上反斜杠。比如Chrome的执行文件地址通常是<code>/Applications/Google\\ Chrome.app/Contents/MacOS/Google\\ Chrome</code></p></div></li><li><p>点击菜单-文件-存储，保存为应用程序，以后通过这个程序启动浏览器就会带着启动项命令。</p></li></ol></details>`,19)])}var d=i(l,[[`render`,u]]);export{c as __pageData,d as default};